}

static unsigned int /* <=== read_u32 */ 
read_u32(Repodata *data)
{
  int c, i;
  unsigned int x = 0;

  if (data->error)
    return 0;
  for (i = 0; i < 4; i++)
    {
      c = getc(data->fp);
      if (c == EOF)
	{
	  data->error = pool_error(data->repo->pool, SOLV_ERROR_EOF, "unexpected EOF");
	  return 0;
	}
      x = (x << 8) | c;
    }
  return x;
}

